import { useState, useCallback } from "react";
import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  BlockStack,
  InlineStack,
  List,
  Button,
  Collapsible,
  CalloutCard,
  Icon,
  Divider,
  Banner,
} from "@shopify/polaris";
import { ChevronDownIcon, ChevronUpIcon } from "@shopify/polaris-icons";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

const faqItems = [
  {
    question: "How do I create my first quiz?",
    answer:
      'Navigate to the Quizzes page and click "Create Quiz." You can choose from a pre-built template or start from scratch. Give your quiz a name, add questions with answer choices, and map each answer to the relevant products in your catalogue. Once you are satisfied, click Publish to make it live on your storefront.',
  },
  {
    question: "How does product mapping work?",
    answer:
      "Product mapping lets you associate specific answer choices with products in your Shopify store. When a customer selects an answer, the mapped products receive a relevance score. At the end of the quiz, the products with the highest combined scores are recommended. You can map individual products or entire collections to each answer choice.",
  },
  {
    question: "Can I customize the quiz appearance?",
    answer:
      'Yes! Open any quiz in the quiz builder and navigate to the Design tab. From there you can customize colors, fonts, button styles, background images, and layout options to match your brand. Changes are previewed in real time before you publish.',
  },
  {
    question: "How is revenue attributed to quizzes?",
    answer:
      "QuizSnap tracks revenue attribution using a 30-day attribution window. When a customer completes a quiz and later purchases a recommended product within 30 days, that revenue is attributed to the quiz. You can view detailed attribution data in the Analytics dashboard.",
  },
  {
    question: "What integrations are available?",
    answer:
      "QuizSnap integrates with Klaviyo, Omnisend, Shopify Flow, and Webhooks. These integrations allow you to sync quiz responses and customer data with your email marketing platform, trigger automated workflows, and send quiz data to any external service.",
  },
  {
    question: "How do I remove QuizSnap branding?",
    answer:
      'QuizSnap branding is displayed on the Free plan. To remove it, upgrade to the Starter plan or above from the Settings page. All paid plans include the option to fully white-label the quiz experience with your own branding.',
  },
];

const videoTutorials = [
  {
    title: "Getting Started with QuizSnap",
    duration: "5 min",
    description:
      "Learn the basics of creating your first product recommendation quiz.",
  },
  {
    title: "Advanced Product Mapping",
    duration: "8 min",
    description:
      "Deep dive into product mapping strategies for accurate recommendations.",
  },
  {
    title: "Maximizing Quiz Conversions",
    duration: "6 min",
    description:
      "Tips and best practices to increase completion rates and conversions.",
  },
];

export default function HelpCenter() {
  const [openFaq, setOpenFaq] = useState<number | null>(null);

  const handleToggleFaq = useCallback(
    (index: number) => {
      setOpenFaq((current) => (current === index ? null : index));
    },
    [],
  );

  return (
    <Page
      title="Help Center"
      subtitle="Everything you need to get started with QuizSnap"
    >
      <BlockStack gap="500">
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd">
                  Quick Start Guide
                </Text>
                <List type="number">
                  <List.Item>
                    Create your first quiz using a template or start from scratch
                  </List.Item>
                  <List.Item>
                    Customize questions to match your product catalogue
                  </List.Item>
                  <List.Item>
                    Map products to answer choices for accurate recommendations
                  </List.Item>
                  <List.Item>
                    Set up email capture to grow your subscriber list
                  </List.Item>
                  <List.Item>
                    Publish and embed the quiz on your storefront
                  </List.Item>
                  <List.Item>
                    Monitor performance in the Analytics dashboard
                  </List.Item>
                </List>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>

        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd">
                  Frequently Asked Questions
                </Text>
                {faqItems.map((item, index) => (
                  <BlockStack gap="200" key={index}>
                    {index > 0 && <Divider />}
                    <Button
                      variant="plain"
                      textAlign="left"
                      onClick={() => handleToggleFaq(index)}
                      icon={
                        openFaq === index ? ChevronUpIcon : ChevronDownIcon
                      }
                      fullWidth
                    >
                      {item.question}
                    </Button>
                    <Collapsible
                      open={openFaq === index}
                      id={`faq-${index}`}
                      transition={{
                        duration: "200ms",
                        timingFunction: "ease-in-out",
                      }}
                    >
                      <BlockStack gap="200">
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {item.answer}
                        </Text>
                      </BlockStack>
                    </Collapsible>
                  </BlockStack>
                ))}
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>

        <Layout>
          <Layout.Section>
            <Text as="h2" variant="headingMd">
              Video Tutorials
            </Text>
          </Layout.Section>
          {videoTutorials.map((video, index) => (
            <Layout.Section key={index} variant="oneThird">
              <Card>
                <BlockStack gap="300">
                  <div
                    style={{
                      background: "#f1f1f1",
                      borderRadius: "8px",
                      height: "140px",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <Text as="p" variant="bodySm" tone="subdued">
                      Video Thumbnail
                    </Text>
                  </div>
                  <BlockStack gap="100">
                    <Text as="h3" variant="headingSm">
                      {video.title}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      {video.duration}
                    </Text>
                  </BlockStack>
                  <Text as="p" variant="bodyMd">
                    {video.description}
                  </Text>
                  <Button variant="plain">Watch Tutorial</Button>
                </BlockStack>
              </Card>
            </Layout.Section>
          ))}
        </Layout>

        <Layout>
          <Layout.Section>
            <CalloutCard
              title="Need more help?"
              illustration="https://cdn.shopify.com/s/assets/admin/checkout/settings-customizecart-702d57c725ac05be5a34ec20c05b94298cb8afd10aac7bd9c7ad02030f48cfa0.svg"
              primaryAction={{
                content: "Contact Support",
                url: "mailto:support@quizsnap.app",
              }}
            >
              <BlockStack gap="200">
                <Text as="p" variant="bodyMd">
                  Our support team is here to help you get the most out of
                  QuizSnap.
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Email: support@quizsnap.app
                </Text>
              </BlockStack>
            </CalloutCard>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}
